engine.askTeamLib:
function askTeamLib() {

  // ─── The greeting (D · team echo) ─────────────────────────────────────
  // i: { name, hour, type: { type, source }, pbOn, pos: undefined (looking) | null (none to look in) | { playbooks, guidance },
  //      prec: { loaded }, tpl: { count, attached: n | 0 }, paras: n | null, theirs: n | null }
  function atGreetingModel(i) {
    i = i || {};
    var n = function (x, one) { return x + " " + one + (x === 1 ? "" : "s"); };
    var type = i.type && i.type.source === "title" && i.type.type && i.type.type !== "Other" ? String(i.type.type) : "";
    var hour = typeof i.hour === "number" ? i.hour : 9;
    var pos = i.pos, pb = (pos && pos.playbooks) || [], gd = ((pos && pos.guidance) || []).length;
    var pbOn = !!i.pbOn && pb.length > 0, locks = pb.filter(function (c) { return c && c.locked; }).length;
    var tpl = i.tpl || {}, tplN = tpl.attached || 0;
    var seals = [{ id: "pb", icon: "book", name: "EI Playbook", off: !pbOn,
      sub: pbOn ? [n(pb.length, "position")].concat(locks ? [n(locks, "lock")] : [])
        : [!i.pbOn ? "switched off" : pos === undefined ? "checking…" : pos === null ? "not available" : "none for this type"] }];
    if (i.prec && i.prec.loaded) seals.push({ id: "pc", icon: "columns", name: "Precedents", sub: ["from past deals"] });
    if (tpl.count > 0) seals.push({ id: "tp", icon: "stack", name: "EI Templates", tap: true, on: tplN > 0,
      sub: [tplN > 0 && tplN < tpl.count ? tplN + " of " + n(tpl.count, "template") : n(tpl.count, "template")] });
    seals.push({ id: "doc", icon: "index", name: "Document", sub: [i.paras == null ? "reading…" : n(i.paras, "paragraph")] });
    var rules = gd ? n(gd, "team rule") : "";
    var foot = tplN > 0 ? { kick: "Templates on", text: "Asking across " + (tplN === 1 ? "1 template" : tplN + " templates") }
      : pbOn ? { kick: "Playbook on", text: "Checked against your positions" + (rules ? " and " + rules : "") }
      : { kick: "Ready", text: rules ? "Answering with " + rules : "Answering from the document" };
    var theirs = i.theirs > 0 ? i.theirs : 0;
    return {
      type: type, kickRight: type || "Document",
      hello: (hour < 12 ? "Good morning" : hour < 18 ? "Good afternoon" : "Good evening") + (i.name ? ", " + i.name : ""),
      sub: "Your " + (type || "document") + ", ready",
      seals: seals, foot: foot, chips: atChips(type, pbOn, tplN > 0),
      respond: theirs ? { n: theirs, text: theirs + " of their changes " + (theirs === 1 ? "is" : "are") + " waiting" } : null,
      placeholder: tplN > 0 ? "Ask about the " + (tplN === 1 ? "template" : tplN + " templates") + "…" : null,
    };
  }
  // Four questions to try: the key terms, the playbook (or what to push back on), two for the agreement type — named only
  // when the title says what it is. Templates attached: one about them first.
  var AT_TYPE_CHIPS = [
    [/clinical/i, ["Who owns the study data and results?", "Can the institution publish, and when?"]],
    [/consumer study/i, ["How is participant data protected?", "Who owns the results?"]],
    [/research/i, ["Who owns the results and IP?", "Can we publish, and when?"]],
    [/material transfer|\bmta\b/i, ["What can the materials be used for?", "Who owns what comes out of the research?"]],
    [/non-?disclosure|confidential|\bnda\b|\bcda\b/i, ["What counts as confidential information?", "How long do the obligations last?"]],
    [/joint development|\bjda\b/i, ["Who owns jointly developed IP?", "How can either side exit?"]],
    [/statement of work|\bsow\b/i, ["What are the deliverables and dates?", "How are changes approved?"]],
    [/consult/i, ["Who owns the work product?", "How are fees and expenses paid?"]],
    [/master services|services|\bmsa\b/i, ["What are the payment terms?", "How can either side terminate?"]],
    [/amendment/i, ["What does this amendment change?", "What stays the same?"]],
    [/renewal/i, ["How long is the renewal?", "What changes on renewal?"]],
    [/termination/i, ["What survives termination?", "What must each side still do?"]],
    [/grant/i, ["How can the grant be used?", "What must the recipient report?"]],
    [/speaker/i, ["What must the speaker do?", "How is the fee paid?"]],
    [/donation/i, ["What conditions come with the donation?", "Can the donation be recognised publicly?"]],
    [/licen[cs]e/i, ["What does the license cover?", "How are royalties paid?"]],
    [/supply/i, ["What are the delivery terms?", "What warranties apply?"]],
  ];
  function atChips(type, pbOn, tplOn) {
    var two = ["What are the key dates and deadlines?", "What are our main obligations?"];
    for (var k = 0; type && k < AT_TYPE_CHIPS.length; k++) if (AT_TYPE_CHIPS[k][0].test(type)) { two = AT_TYPE_CHIPS[k][1]; break; }
    var qs = [{ text: "Summarize the key terms" }, { text: pbOn ? "Where does this depart from our playbook?" : "What would you push back on?" },
      { text: two[0] }, { text: two[1] }];
    return tplOn ? [{ text: "Which templates have a non-solicit?", tag: "Templates" }].concat(qs.slice(0, 3)) : qs;
  }

  // ─── Forge: is this question about ELI itself? ────────────────────────
  // A question goes to Forge only when it names ELI, one of its tools or parts, or Word misbehaving, AND asks about
  // set-up: something missing, an update, slowness, an error, a setting, what's new, how to use a tool. A question about
  // the document ("why doesn't this NDA have a non-compete?") never does. → { kind, tool } | null
  var AT_TOOLS = [
    // [id, name, pattern (in any case, the tool named as a product), capitalised name alone counts too]
    ["respond", "Respond", /\brespond(?:\s+to\s+(?:redlines|all))?\s+(?:button|tool|agent|tile|feature|option|mode)\b|\b(?:the|new|a)\s+respond\s+(?:button|tool|agent)\b/i, /\bRespond\b/],
    ["revise", "Revise", /\brevise(?:\s+document)?\s+(?:button|tool|agent|mode|feature)\b/i, /\bRevise\b/],
    ["address_comments", "Address Comments", /\baddress comments\b/i, null],
    ["draft_document", "Draft Document", /\bdraft document\s+(?:agent|tool|mode)\b/i, /\bDraft Document\b/],
    ["build_draft", "Build Draft", /\bbuild draft\b/i, null],
    ["polish", "Polish", /\bpolish\s+(?:button|tool|feature)\b/i, /\bPolish\b/],
    ["error_review", "Error Review", /\berror review\b/i, null],
    ["final_review", "Final Review", /\bfinal review\b/i, null],
    ["legal_review", "Legal Review", /\blegal review\b/i, null],
    ["review_redlines", "Review Redlines", /\breview redlines\b/i, null],
    ["compare", "Compare to Template", /\bcompare to template\b|\bcompare\s+(?:tool|tile)\b/i, null],
    ["format_check", "Format Check", /\bformat check\b/i, null],
    ["template_revise", "Template Revise", /\btemplate revise\b/i, null],
    ["defined_terms", "Defined Terms", /\bdefined terms\s+(?:tool|tile)\b/i, null],
    ["docuscrub", "DocuScrub", /\bdocuscrub\b/i, null],
    ["text_helper", "Text Helper", /\btext helper\b|\bemail helper\b/i, null],
    ["agreement_glance", "Agreement at a Glance", /\bagreement at a glance\b/i, null],
    ["whats_new", "What's New", /\bwhat'?s new\s+(?:tile|window|screen|page)\b/i, null],
    ["data_hub", "Data Hub", /\bdata hub\b/i, null],
    ["ask_eli", "Ask ELI", /\bask eli\s+(?:button|panel|chat|window|box|tool|settings)\b/i, null],
  ];
  function atForgeTopic(q) {
    var raw = String(q || "").replace(/[‘’]/g, "'");
    var s = " " + raw.toLowerCase().replace(/\s+/g, " ") + " ";
    if (!s.trim() || s.length > 400) return null;   // (a pasted clause is never a set-up question)
    var tool = null;
    for (var k = 0; k < AT_TOOLS.length && !tool; k++) if (AT_TOOLS[k][2].test(s) || (AT_TOOLS[k][3] && AT_TOOLS[k][3].test(raw))) tool = AT_TOOLS[k][0];
    var eli = /\beli\b|\beli'?s\b|\badd-?in\b|\btask ?pane\b|\bscript lab\b|\bsnippet\b|\bdashboard\b|\bthe (?:panel|sidebar)\b|\beli os\b/.test(s);
    var word = /\b(?:ms |microsoft )?word\b/.test(s) && !/\bword(?:s|ing|ed)\b|\bthe word "|\bword for word\b/.test(s);
    var feature = /\b(?:button|tile|icon|tool|agent|setting|settings|version|update|updates|add-?in|api key|gemini key|toggle|switch|menu|feature)\b/.test(s);
    var docNoun = /\b(?:this|the|our|their|that) (?:agreement|contract|clause|section|document|doc|draft|nda|msa|sow|amendment|redline|redlines|party|parties|term|terms|template|indemnity|warranty)\b/.test(s);
    var missing = /\b(?:don'?t|do not|can'?t|cannot|doesn'?t|does not|won'?t|isn'?t|is not|aren'?t|not)\b[^.?!]{0,30}\b(?:have|see|find|show|showing|appear|appearing|available|there|work|working|load|loading|open|opening)\b|\bwhere(?:'s| is| are| did| has| have)\b|\bmissing\b|\bdisappeared\b|\bgone\b|\bgr[ae]yed out\b/.test(s);
    var update = /\b(?:update|updates|updated|updating|upgrade|version|build|latest|out of date|up to date|reinstall|re-?import|import link)\b/.test(s);
    var slow = /\b(?:freez\w*|frozen|hang(?:s|ing)?|hung|slow\w*|lag\w*|stuck|spinning|not responding|crash\w*|takes (?:forever|ages|so long|a long time))\b/.test(s);
    var error = /\b(?:error|errors|bug|broken|glitch\w*|blank|white screen|won'?t (?:load|open|start)|fail\w*)\b/.test(s);
    var setting = /\b(?:setting|settings|turn (?:on|off)|switch (?:on|off)|enable|disable|preferences?|api key|gemini key|dark mode|light mode|theme|mascot)\b/.test(s);
    var howto = /\bhow (?:do|can|should) (?:i|we)\b|\bhow to\b|\bwhat does\b[^?]{0,30}\b(?:button|tool|agent|setting|tile)\b|\bcan eli\b|\bdoes eli\b|\bwhat is (?:eli|the eli)\b/.test(s);
    var news = /\bwhat'?s new\b|\bwhat is new\b|\bwhat (?:has )?changed\b|\bnew features?\b|\brelease notes\b|\blatest release\b/.test(s);
    var product = !!tool || eli;
    // Word misbehaving is set-up even without ELI named; Word alone with a feature word too ("my Word build").
    var wordTrouble = word && (slow || error || (update && feature));
    if (!product && !wordTrouble) return null;
    // A document noun with only "ELI" named needs a feature word too: "ELI, why doesn't this NDA have a non-compete?" stays ELI's.
    if (docNoun && !tool && !feature && !wordTrouble) return null;
    if (news && (eli || tool)) return { kind: "whats_new", tool: tool };
    if (slow && (eli || word || tool)) return { kind: "slow", tool: tool };
    if (tool && missing) return { kind: "missing", tool: tool };
    if (update && (eli || tool || feature)) return { kind: "update", tool: tool };
    if (error && (eli || word || tool)) return { kind: "error", tool: tool };
    if (missing && feature && eli) return { kind: "missing", tool: null };
    if (setting && (eli || tool)) return { kind: "setting", tool: tool };
    if (howto && (tool || eli)) return { kind: "howto", tool: tool };
    if (tool && feature && !docNoun) return { kind: "howto", tool: tool };
    return null;
  }
  // A question put to Forge that's plainly about the document (back to ELI with it).
  function atForgeIsDocQuestion(q) {
    var t = atForgeTopic(q);
    if (t) return false;
    var s = " " + String(q || "").toLowerCase() + " ";
    return /\b(?:this|the|our|their) (?:agreement|contract|clause|section|document|draft|nda|msa|amendment|redline|party|parties)\b|\bsection \d|\bclause \d|\barticle \d/.test(s);
  }
  // Forge's own words for a "thanks / done / ok" (ELI takes over again).
  function atForgeIsThanks(q) {
    return /^\s*(?:thanks?|thank you|thx|ty|ok(?:ay)?|got it|great|perfect|done|cool|all good|that'?s it|no(?: thanks)?|nope)[\s.!]*$/i.test(String(q || ""));
  }

  // ─── Forge's checks ───────────────────────────────────────────────────
  // An ELI OS version ("v3-2026-10-20-2013-e96510b") as people say it: build 2013, of Oct 20.
  function atBuildName(v) {
    var m = /^v\d+-(\d{4})-(\d{2})-(\d{2})-(\d{4})/.exec(String(v || ""));
    if (!m) return String(v || "unknown");
    var mon = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"][+m[2] - 1] || m[2];
    return m[4] + " (" + mon + " " + (+m[3]) + ")";
  }
  // What each tool needs from Word (the WordApi sets its code checks for).
  var AT_NEEDS = { respond: ["1.6", "1.4"], address_comments: ["1.4"], format_check: ["1.3"], revise: ["1.4"] };
  // kind, tool, facts (init's live reads) → { lead, checks: [{ state: ok|warn|info, label, value }], actions: [{ id, label, sub }],
  // links: [{ id, label }], done } — done: nothing more to do here, ELI takes over again after it.
  // facts: { kernel: { running, latest, state }, word: { version, api: { "1.3": bool, … } } | null,
  //   tool: { id, name, released, everyone, installed, disabled, update, waitsForKernel } | null, respondAll, theirs,
  //   updates, perf: { freezes, longest, longestTool, bootMs } | null, paragraphs, notes: { title, items } | null, admins: [names] }
  function atForgeReport(kind, toolId, f) {
    f = f || {};
    var checks = [], actions = [], links = [];
    var k = f.kernel || {}, w = f.word, t = f.tool, admin = (f.admins && f.admins[0]) || "the ELI team";
    var behind = k.state === "behind";
    var kernelCheck = function () {
      checks.push(k.state === "current" ? { state: "ok", label: "ELI OS build", value: atBuildName(k.running) + " · current" }
        : behind ? { state: "warn", label: "ELI OS build", value: atBuildName(k.running).replace(/ \(.*/, "") + " · published " + atBuildName(k.latest).replace(/ \(.*/, "") }
        : { state: "info", label: "ELI OS build", value: atBuildName(k.running) + (k.state === "ahead" ? " · ahead of published" : " · couldn't check") });
    };
    var needs = (toolId && AT_NEEDS[toolId]) || ["1.3"];
    var wordOk = !w || !w.api ? null : needs.every(function (v) { return w.api[v]; });
    var wordCheck = function () {
      var ver = w && w.version ? String(w.version).split(".").slice(0, 3).join(".") : "";
      checks.push(wordOk === null ? { state: "info", label: "Word build", value: ver || "couldn't read it" }
        : wordOk ? { state: "ok", label: "Word build", value: ver + " · supported" }
        : { state: "warn", label: "Word build", value: ver + " · too old" + (t ? " for " + t.name : "") });
    };
    var update = { id: "kernel_update", label: "Open ELI OS Update", sub: "About a minute · your document stays as it is" };
    var notNow = { id: "not_now", label: "Not now" };
    var lead = "";
    if (kind === "missing" && t) {
      kernelCheck(); wordCheck();
      var rel = !t.released ? { state: "warn", value: "not released to you yet" } : t.disabled ? { state: "warn", value: "switched off here" }
        : t.waitsForKernel ? { state: "warn", value: "needs a newer ELI OS" } : !t.installed ? { state: "warn", value: "not installed yet" }
        : t.update ? { state: "warn", value: "a newer copy is waiting" } : { state: "ok", value: t.everyone ? "released to everyone" : "installed" };
      checks.push({ state: rel.state, label: t.name, value: rel.value });
      var isRespond = toolId === "respond";
      if (isRespond && rel.state === "ok") {   // (Respond's own rows only once Respond itself is fine: the card leads with the cause)
        checks.push(f.respondAll ? { state: "ok", label: "Respond in the box", value: "on" } : { state: "warn", label: "Respond in the box", value: "switched off" });
        if (f.theirs != null) checks.push(f.theirs > 0 ? { state: "ok", label: "This document", value: f.theirs + " of their changes" }
          : { state: "info", label: "This document", value: f.theirs === 0 ? "no changes of theirs" : "couldn't count them" });
      }
      if (behind && (t.waitsForKernel || !t.installed)) {
        lead = "Found it. " + t.name + " needs ELI OS build " + atBuildName(k.latest).replace(/ \(.*/, "") + ", and this computer is still on " + atBuildName(k.running).replace(/ \(.*/, "") + ".";
        actions.push(update); links.push(notNow);
      } else if (!t.released) {
        lead = t.name + " hasn't been released to you yet; it's still with the ELI team. Nothing on this computer is wrong.";
        links.push({ id: "back", label: "Back to ELI" });
      } else if (t.disabled) {
        lead = t.name + " is switched off on this computer; the ELI team may have paused it. Ask " + admin + " before turning it back on.";
        links.push({ id: "back", label: "Back to ELI" });
      } else if (!t.installed || t.update) {
        lead = (t.installed ? "A newer " + t.name + " is waiting" : t.name + " hasn't installed yet") + ". Data Hub's Check for Updates installs it.";
        actions.push({ id: "data_hub", label: "Open Data Hub", sub: "Check for Updates · your document stays as it is" }); links.push(notNow);
      } else if (wordOk === false) {
        lead = t.name + " needs a newer Word" + (isRespond ? ": it answers the other side's changes one at a time, which this Word can't do" : "") +
          ". Ask your IT team to update Office, then reopen ELI.";
        links.push({ id: "back", label: "Back to ELI" });
      } else if (isRespond && !f.respondAll) {
        lead = "Respond to all is switched off in Ask ELI's settings, so the button only shows when you highlight a change of theirs.";
        actions.push({ id: "ask_settings", label: "Open Ask ELI settings", sub: "Agents tab · Respond in the box" }); links.push(notNow);
      } else if (isRespond && f.theirs === 0) {
        lead = "Respond is ready, but this document has no tracked changes from the other side. The gold Respond button appears below the question box as soon as it does.";
        links.push({ id: "back", label: "Back to ELI" });
      } else if (behind) {
        lead = t.name + " is installed and ready. One thing: ELI OS build " + atBuildName(k.latest).replace(/ \(.*/, "") + " is out and this computer is on " + atBuildName(k.running).replace(/ \(.*/, "") + ".";
        actions.push(update); links.push(notNow);
      } else {
        lead = isRespond ? "Respond is ready: it's the gold Respond button below the question box" + (f.theirs > 0 ? ", with all " + f.theirs + " of their changes" : "") + "."
          : t.name + " is installed and ready on this computer.";
        if (isRespond && f.theirs > 0) actions.push({ id: "respond", label: "Open Respond", sub: "Answers their changes · nothing is written until you approve" });
        links.push({ id: "back", label: "Back to ELI" });
      }
    } else if (kind === "update" || (kind === "missing" && !t)) {
      kernelCheck();
      checks.push(f.updates > 0 ? { state: "warn", label: "Tools", value: f.updates + " update" + (f.updates === 1 ? "" : "s") + " waiting" } : { state: "ok", label: "Tools", value: "all current" });
      wordCheck();
      if (behind) { lead = "ELI OS build " + atBuildName(k.latest).replace(/ \(.*/, "") + " is out; this computer is on " + atBuildName(k.running).replace(/ \(.*/, "") + "."; actions.push(update); links.push(notNow); }
      else if (f.updates > 0) { lead = f.updates + " tool update" + (f.updates === 1 ? " is" : "s are") + " waiting. Data Hub's Check for Updates installs " + (f.updates === 1 ? "it" : "them") + ".";
        actions.push({ id: "data_hub", label: "Open Data Hub", sub: "Check for Updates · your document stays as it is" }); links.push(notNow); }
      else { lead = k.state === "current" ? "You're up to date: ELI OS and every tool." : "Every tool is current. I couldn't reach the server to check ELI OS itself just now."; links.push({ id: "back", label: "Back to ELI" }); }
    } else if (kind === "slow") {
      kernelCheck(); wordCheck();
      var p = f.perf;
      if (p) checks.push(p.freezes > 0 ? { state: p.longest >= 2000 ? "warn" : "info", label: "Pauses this session", value: p.freezes + (p.freezes === 1 ? " pause" : " pauses") + ", longest " + (Math.round(p.longest / 100) / 10) + " s" }
        : { state: "ok", label: "Pauses this session", value: "none" });
      if (f.paragraphs != null) checks.push({ state: f.paragraphs > 600 ? "info" : "ok", label: "This document", value: f.paragraphs + " paragraphs" + (f.paragraphs > 600 ? " · long" : "") });
      if (behind) { lead = "This computer is on an older ELI OS (" + atBuildName(k.running).replace(/ \(.*/, "") + "; " + atBuildName(k.latest).replace(/ \(.*/, "") + " is out). Updating often fixes slowness."; actions.push(update); links.push(notNow); }
      else if (p && p.longest >= 2000 && p.longestTool) { lead = "The longest pause (" + (Math.round(p.longest / 100) / 10) + " s) came while " + p.longestTool + " was opening. If it keeps happening there, tell " + admin + "."; links.push({ id: "back", label: "Back to ELI" }); }
      else if (f.paragraphs > 600) { lead = "This is a long document. ELI reads it once when Ask ELI opens, which can hold Word for a few seconds; answers after that are quick."; links.push({ id: "back", label: "Back to ELI" }); }
      else { lead = "Nothing on this computer looks wrong. If Word keeps freezing, close other Word windows and restart Word; if it continues, tell " + admin + "."; links.push({ id: "back", label: "Back to ELI" }); }
    } else if (kind === "whats_new") {
      kernelCheck();
      var nt = f.notes;
      lead = nt && nt.items && nt.items.length ? "Here's what's new" + (nt.title ? " in " + nt.title : "") + ":" : "There are no release notes on this computer yet.";
      if (nt && nt.items && nt.items.length) { actions.push({ id: "whats_new", label: "Open What's New", sub: "The full notes" }); links.push({ id: "back", label: "Back to ELI" }); }
      else if (behind) { actions.push(update); links.push(notNow); }
      else links.push({ id: "back", label: "Back to ELI" });
      return { lead: lead, list: nt && nt.items ? nt.items.slice(0, 5) : [], checks: [], actions: actions, links: links, done: !actions.length };
    } else {
      return null;   // setting, howto, error, a question Forge doesn't check for: its knowledge (FAQ or AI) answers
    }
    return { lead: lead, list: [], checks: checks, actions: actions, links: links, done: !actions.length };
  }

  // ─── Forge's knowledge: the FAQ entry that answers a question ─────────
  // kb.faq: [{ q, keys: [...], a, action }] → the best entry (most of its keys in the question, at least two) or null.
  function atForgeFaq(question, kb) {
    var s = " " + String(question || "").toLowerCase().replace(/[‘’]/g, "'") + " ", best = null, bestN = 1;
    ((kb && kb.faq) || []).forEach(function (e) {
      var hit = (e.keys || []).filter(function (k) { return s.indexOf(String(k).toLowerCase()) !== -1; }).length;
      if (hit > bestN || (hit === bestN && best && (e.keys || []).length < (best.keys || []).length)) { if (hit > 1) { best = e; bestN = hit; } }
    });
    return best;
  }
  // The prompt for a question the FAQ doesn't answer: ELI's knowledge pack and the live checks, nothing of the document.
  var AT_FORGE_ACTIONS = { ask_settings: "Ask ELI's settings", eli_settings: "ELI's Settings (API key, display)", kernel_update: "ELI OS Update",
    data_hub: "Data Hub (Check for Updates, turn tools on or off)", whats_new: "What's New" };
  function atForgePrompt(question, kb, facts) {
    return [
      "You are Forge, the IT Support agent on ELI's team. ELI is a Word add-in for contract review used by a legal team.",
      "Answer the user's question about ELI itself: its tools, settings, updates, or Word's behaviour with it.",
      "Use only the KNOWLEDGE and FACTS below. If they don't say, say you don't know and suggest asking " + (((facts && facts.admins) || [])[0] || "the ELI team") + ".",
      "Two to four short sentences, plain words, no headings or lists. Never ask for, mention or reveal API keys, passwords or tokens.",
      "Never suggest changing the document. You only read; anything you offer, the user chooses.",
      "If one of these would help, end with exactly one tag on its own line: [[open:ID]] where ID is one of: " +
        Object.keys(AT_FORGE_ACTIONS).map(function (k) { return k + " (" + AT_FORGE_ACTIONS[k] + ")"; }).join(", ") + ".",
      "",
      "KNOWLEDGE:", String((kb && kb.text) || ""),
      "",
      "FACTS (this computer, read just now):", JSON.stringify(facts || {}),
      "",
      "QUESTION: " + String(question || ""),
    ].join("\n");
  }
  // The answer's text and the one action it asks for (an allowed id only).
  function atForgeAnswer(text) {
    var s = String(text || ""), m = /\[\[open:([a-z_]+)\]\]\s*$/.exec(s.trim());
    var id = m && AT_FORGE_ACTIONS[m[1]] ? m[1] : null;
    return { text: s.replace(/\[\[open:[a-z_]+\]\]/g, "").replace(/\s+$/, "").trim(), action: id };
  }

  // ─── EI templates: the text, and the parts that answer a question ──────
  // A Build Draft template row's content (its Word package as JSON, or plain text) → its paragraphs: tracked deletions
  // and field codes dropped, {{IF:…}} logic and [[…]] fill-ins kept (they say which version of a clause is which).
  function atTemplateText(content) {
    var c = content;
    if (typeof c === "string") { try { c = JSON.parse(c); } catch (_) { c = { body: c }; } }
    var body = String((c && (c.body || c.content)) || "");
    var m = /pkg:name="\/word\/document\.xml"[\s\S]*?<w:body>([\s\S]*?)<\/w:body>/.exec(body);
    var xml = m ? m[1] : body.indexOf("<w:p") !== -1 ? body : "";
    var text = !xml ? body : xml
      .replace(/<w:delText\b[^>]*>[\s\S]*?<\/w:delText>/g, "").replace(/<w:instrText\b[^>]*>[\s\S]*?<\/w:instrText>/g, "")
      .replace(/<w:p\b[^>]*\/>/g, "\n").replace(/<\/w:p>/g, "\n").replace(/<w:br\b[^>]*\/?>/g, "\n").replace(/<w:tab\b[^>]*\/?>/g, " ")
      .replace(/<[^>]+>/g, "")
      .replace(/&lt;/g, "<").replace(/&gt;/g, ">").replace(/&quot;/g, '"').replace(/&apos;/g, "'").replace(/&#(\d+);/g, function (_, d) { return String.fromCharCode(+d); }).replace(/&amp;/g, "&");
    return text.split(/\n/).map(function (l) { return l.replace(/[ \t ]+/g, " ").trim(); }).filter(Boolean);
  }
  // Words of a question or a paragraph, cut to a stem (plural, -ing, -ed, -ion endings off; six letters): "terminate" and
  // "termination" meet, so do "solicit" and "non-solicitation".
  var AT_STOP = " the and for are but not you all any can had her was one our out has have this that with from they will would there their what which when where who why how does did into about your than then them these those its also may shall such each other under upon been were more most some only over very just like make made using used use per via within without between whether templates template agreement agreements ";
  function atStems(s) {
    return String(s || "").toLowerCase().replace(/[‘’]/g, "'").split(/[^a-z0-9]+/).filter(function (w) {
      return w.length >= 3 && AT_STOP.indexOf(" " + w + " ") === -1;
    }).map(function (w) { return w.replace(/(?:ations?|ions?|ings?|ed|es|s)$/, "").slice(0, 6); }).filter(function (w) { return w.length >= 3; });
  }
  var AT_TPL_ALIAS = { msa: "master services", nda: "non-disclosure", cda: "non-disclosure", sow: "statement of work", mta: "material transfer",
    jda: "joint development", csa: "clinical study" };
  // lib: [{ id, name, type, paras }] → the text sent with this question: every template named, then the parts that answer
  // it (each with its heading), the templates the question names whole while they fit; cap: characters.
  function atTemplatePick(question, lib, cap) {
    cap = cap || 120000;
    lib = lib || [];
    var q = String(question || ""), ql = " " + q.toLowerCase() + " ";
    Object.keys(AT_TPL_ALIAS).forEach(function (a) { if (new RegExp("\\b" + a + "s?\\b").test(ql)) ql += " " + AT_TPL_ALIAS[a] + " "; });
    // a template is named by its name without "Agreement": two words, or one followed by "agreement"/"template"
    // ("our MSA", "the research agreement", "the amendment template"); of two names, the longer wins (master services)
    var stem = function (t) { return String(t.name || "").toLowerCase().replace(/\s+-\s+.*$/, "").replace(/\s+agreement$/, "").trim(); };
    var named = lib.filter(function (t) {
      var nm = stem(t), at = ql.indexOf(nm);
      return nm.length > 3 && at !== -1 && (/\s/.test(nm) || /^\s+(?:agreement|template)\b/.test(ql.slice(at + nm.length)));
    });
    named = named.filter(function (t) { return !named.some(function (o) { return o !== t && stem(o).length > stem(t).length && stem(o).indexOf(stem(t)) !== -1; }); });
    var head = "=== ATTACHED EXTERNAL REFERENCE: EI templates (" + lib.length + ") ===\n" +
      "The team's own templates (Build Draft's library). {{IF:…}} / {{ELSE}} / {{END IF}} mark alternative versions of the text; [[…]] are fill-ins.\n" +
      "All of them: " + lib.map(function (t) { return t.name + (t.type ? " (" + t.type + ")" : ""); }).join("; ") + ".\n";
    var out = head, left = cap - head.length;
    var isHead = function (l) { return l.length < 90 && !/[.;:,]$/.test(l) && /^[\dA-Z(]/.test(l); };
    var section = function (t, lines, whole) { return "\n--- " + t.name + (whole ? " (whole template)" : " (the parts that bear on the question)") + " ---\n" + lines.join("\n") + "\n"; };
    // the templates the question names, whole, while they fit
    var done = {};
    named.forEach(function (t) {
      var s = section(t, t.paras || [], true);
      if (s.length <= left) { out += s; left -= s.length; done[t.id] = 1; }
    });
    // the parts of the rest that answer it: each paragraph scored by the question's words it holds (rarer words count more)
    // the question's own words, less those that only ask for an overview ("summarize", "compare", "list")
    var GENERIC = " summar overvi explai descri compar differ list tell show give key main point these those ";
    var qs = atStems(q).filter(function (w, i, a) { return a.indexOf(w) === i && GENERIC.indexOf(" " + w + " ") === -1; });
    if (qs.length) {
      var df = {}, total = 0;
      var pool = (named.length ? named : lib).filter(function (t) { return !done[t.id]; });
      var scored = pool.map(function (t) {
        return (t.paras || []).map(function (p) { total++; var st = atStems(p); var has = {}; st.forEach(function (w) { has[w] = 1; }); Object.keys(has).forEach(function (w) { df[w] = (df[w] || 0) + 1; }); return has; });
      });
      var picks = [];
      pool.forEach(function (t, ti) {
        scored[ti].forEach(function (has, pi) {
          var sc = 0;
          qs.forEach(function (w) { if (has[w]) sc += Math.log(1 + total / (df[w] || 1)); });
          if (sc > 0) picks.push({ ti: ti, pi: pi, sc: sc });
        });
      });
      picks.sort(function (a, b) { return b.sc - a.sc; });
      var top = picks.length ? picks[0].sc : 0, keep = {};
      picks.forEach(function (x) { if (x.sc >= top * 0.5) (keep[x.ti] = keep[x.ti] || []).push(x); });
      Object.keys(keep).map(Number).sort(function (a, b) { return keep[b][0].sc - keep[a][0].sc; }).forEach(function (ti) {
        var t = pool[ti], paras = t.paras || [], want = {};
        keep[ti].forEach(function (x) {
          want[x.pi] = 1;
          for (var h = x.pi - 1; h >= 0 && h >= x.pi - 12; h--) if (isHead(paras[h])) { want[h] = 1; break; }   // its heading
          if (isHead(paras[x.pi]) && x.pi + 1 < paras.length) want[x.pi + 1] = 1;                              // a heading: its text
        });
        var lines = Object.keys(want).map(Number).sort(function (a, b) { return a - b; }).map(function (i) { return paras[i]; });
        var s = section(t, lines, false);
        if (s.length > left) { lines = lines.slice(0, Math.max(1, Math.floor(lines.length * left / s.length))); s = section(t, lines, false); }
        if (s.length <= left) { out += s; left -= s.length; done[t.id] = 1; }
      });
    }
    // nothing in them answers it word for word ("summarize these"): each template's headings, as far as they fit
    if (out === head) {
      lib.forEach(function (t) {
        var hs = (t.paras || []).filter(isHead).slice(0, 60), s = section(t, hs, false).replace("the parts that bear on the question", "its headings");
        if (s.length <= left) { out += s; left -= s.length; }
      });
    }
    return out;
  }

  function atToolName(id) { for (var k = 0; k < AT_TOOLS.length; k++) if (AT_TOOLS[k][0] === id) return AT_TOOLS[k][1]; return ""; }

  return { greeting: atGreetingModel, chips: atChips, topic: atForgeTopic, toolName: atToolName, isDocQuestion: atForgeIsDocQuestion, isThanks: atForgeIsThanks,
    buildName: atBuildName, report: atForgeReport, faq: atForgeFaq, prompt: atForgePrompt, answer: atForgeAnswer, actions: AT_FORGE_ACTIONS,
    templateText: atTemplateText, stems: atStems, templatePick: atTemplatePick };
}

