jsonTools.init:
function init(eli) {
  if (!eli || !eli.register) return;
  var bundle = (eli.tools && eli.tools._loaded && eli.tools._loaded.ask_eli_team) || {};
  var Lib = (bundle._eliEngineFns && bundle._eliEngineFns.askTeamLib) || (typeof askTeamLib === "function" ? askTeamLib : null);
  var ViewF = (bundle._eliViewFns && bundle._eliViewFns.askTeamView) || (typeof askTeamView === "function" ? askTeamView : null);
  if (!Lib || !ViewF) { eli.log.event("tool", "ask_eli_team_missing_fns", { lib: !!Lib, view: !!ViewF }); return; }
  var L = Lib(), V = ViewF();
  var KB = typeof askTeamKnowledge === "function" ? askTeamKnowledge() : { faq: [], text: "" };
  var STEP_MS = 350, HANDOVER_MS = 900, ARRIVE_MS = 1300;   // the hand-over's beats; each check ticks in on its own
  var wait = function (ms) { return new Promise(function (r) { setTimeout(r, ms); }); };
  var calm = function () { try { return !!(window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches); } catch (_) { return false; } };
  function el(tag, cls, html) { var d = document.createElement(tag); if (cls) d.className = cls; if (html != null) d.innerHTML = html; return d; }
  function within(p, ms) { return Promise.race([Promise.resolve(p), wait(ms).then(function () { return null; })]).catch(function () { return null; }); }

  // ─── The EI templates: Build Draft's library, as this user's audience sees it ───
  // listAvailableTemplates filters by audience; the text comes from the copies on this computer (Build Draft's
  // listTemplates), any not yet downloaded fetched once (fetchTemplate, Build Draft's own download).
  function listTemplates() {
    return within(eli.dispatch("build_draft", "listAvailableTemplates"), 8000).then(function (rows) {
      return (Array.isArray(rows) ? rows : []).filter(function (t) { return t && t.id && String(t.id).charAt(0) !== "_"; });
    });
