/* tools/ask_eli_team/style.css — Ask ELI Team: the greeting (D · team echo, the EI Templates seal), the templates
   picker, Forge in the chat. Light in both themes (the chat is). One accent: gold #c9a227; navy #13294b; slate text. */

/* ─── The greeting ───────────────────────────────────────────────── */
._eli3_chat_bubble_welcome.at-welcome { padding: 2px 0 14px; }
.at-greet, .at-greet * { box-sizing: border-box; }
.at-greet { width: 100%; max-width: 720px; margin: 0 auto; font: 400 12px/1.45 Inter, 'Segoe UI', sans-serif; color: #0f1f3d; }
.at-kick { font: 700 9.5px/1 Inter, sans-serif; letter-spacing: .16em; text-transform: uppercase; color: #8a6a00; }
.at-kick-r { color: #64748b; text-align: right; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.at-frame { background: #f5f7fa; border: 1px solid #c9a227; padding: 4px; }
.at-frame-in { border: 1px solid #c8d1de; background: #fff; padding: 12px 10px 0; }
.at-top { display: flex; justify-content: space-between; align-items: center; gap: 10px; }
.at-sl { display: block; flex: 0 0 auto; }

.at-tree { margin: 8px 0 0; display: flex; flex-direction: column; align-items: center; }
.at-lead { display: flex; align-items: center; gap: 9px; max-width: 100%; }
.at-ms { width: 40px; height: 40px; flex: 0 0 40px; display: inline-flex; align-items: flex-end; justify-content: center; overflow: hidden; cursor: pointer;
  background: radial-gradient(circle at 50% 35%, #fbf6e4, #f1e3b0); border: 2px solid #c9a227; box-shadow: 0 0 0 2px #fff, 0 0 0 3px rgba(201, 162, 39, .6); }
.at-ms svg { width: 96%; height: 96%; margin-bottom: -6%; }
.at-lead-t { min-width: 0; }
.at-lead-t b { display: block; font: 400 17px/1.15 Georgia, 'Times New Roman', serif; color: #0f1f3d; }
.at-lead-t span { display: block; font: italic 11px/1.3 Georgia, serif; color: #64748b; }
.at-stem { width: 1px; height: 16px; background: #c9a227; margin-top: 6px; }
.at-row { position: relative; display: grid; grid-template-columns: repeat(var(--at-n, 3), minmax(0, 1fr)); width: 100%; padding-top: 16px; }
.at-bar { position: absolute; top: 0; height: 1px; background: #c9a227; left: calc(50% / var(--at-n, 3)); right: calc(50% / var(--at-n, 3)); }
.at-node { position: relative; display: flex; flex-direction: column; align-items: center; text-align: center; min-width: 0; padding: 0 2px 12px; }
.at-node::before { content: ""; position: absolute; top: -16px; left: 50%; width: 1px; height: 18px; background: #c9a227; }
.at-sealbox { position: relative; display: block; }
.at-node b { font: 400 14px/1.15 Georgia, serif; color: #0f1f3d; margin-top: 3px; white-space: nowrap; }
.at-sub { font: italic 11px/1.25 Georgia, serif; color: #64748b; white-space: nowrap; }
.at-dot { font-style: inherit; }
.at-node.is-off b, .at-node.is-off .at-sub { color: #94a3b8; }
/* four seals on a narrow pane: smaller names, a seal's two facts on two lines */
@media (max-width: 599px) {
  .at-n4 .at-node b { font-size: 12.5px; }
  .at-n4 .at-sub { font-size: 10.5px; }
  .at-n4 .at-sub1 { display: block; }
  .at-n4 .at-dot { display: none; }
}
@media (max-width: 340px) { .at-node b { white-space: normal; } .at-sub { white-space: normal; } }

/* the seal you can tap: EI Templates */
.at-tap { cursor: pointer; outline: none; }
.at-plus { position: absolute; top: 2px; right: -3px; width: 15px; height: 15px; background: #c9a227; color: #13294b; font: 700 11px/15px Inter, sans-serif; text-align: center; box-shadow: 0 0 0 2px #fff; }
.at-tap.is-on .at-plus { background: #13294b; color: #e5cc80; }
.at-act { margin-top: 4px; font: 700 8.5px/1 Inter, sans-serif; letter-spacing: .14em; text-transform: uppercase; color: #8a6a00; border-bottom: 1px dashed #c9a227; padding-bottom: 2px; font-style: normal; }
.at-tap.is-on .at-act { color: #15803d; border-bottom-color: #15803d; }
.at-tap:hover .at-sl, .at-tap:focus-visible .at-sl { filter: drop-shadow(0 0 3px rgba(201, 162, 39, .55)); }
.at-tip { display: none; position: absolute; z-index: 5; top: 100%; left: 50%; transform: translateX(-62%); width: 228px; margin-top: -4px; padding: 9px 11px;
  background: #13294b; color: #fff; text-align: left; box-shadow: 0 6px 16px rgba(10, 22, 48, .25), inset 0 0 0 1px #c9a227; pointer-events: none; }
.at-tip::before { content: ""; position: absolute; top: -6px; left: 62%; width: 10px; height: 10px; margin-left: -5px; background: #13294b; transform: rotate(45deg); box-shadow: -1px -1px 0 #c9a227; }
.at-tip b { display: block; font: 400 14px/1.2 Georgia, serif; color: #fff; margin: 0; white-space: normal; }
.at-tip span { display: block; font: 400 11px/1.35 Inter, sans-serif; color: #9aa9c2; margin-top: 3px; white-space: normal; }
@media (hover: hover) { .at-tap:hover .at-tip { display: block; } }
.at-tap:focus-visible .at-tip { display: block; }

.at-foot { display: flex; align-items: center; gap: 10px; margin: 2px -10px 0; padding: 10px 12px; border-top: 1px solid #c9a227; background: linear-gradient(180deg, #fff, #fbf6e4); }
.at-foot .at-kick { white-space: nowrap; padding-right: 10px; border-right: 1px solid #c9a227; }
.at-foot i { font: italic 400 16px/1.15 Georgia, serif; color: #13294b; min-width: 0; }

.at-lbl { font: 700 9px/1 Inter, sans-serif; letter-spacing: .16em; text-transform: uppercase; color: #64748b; margin: 14px 0 7px; }
.at-chips { display: flex; flex-direction: column; gap: 6px; }
@media (min-width: 600px) { .at-chips { display: grid; grid-template-columns: 1fr 1fr; } }
.at-chip { display: flex; align-items: center; gap: 9px; width: 100%; text-align: left; background: #fff; border: 1px solid #d6dee9; border-radius: 0; padding: 8px 11px;
  font: 400 13px/1.25 Georgia, serif; color: #13294b; cursor: pointer; }
.at-chip:hover { border-color: #c9a227; }
.at-chip i { width: 6px; height: 6px; background: #c9a227; transform: rotate(45deg); flex: 0 0 auto; }
.at-chip span { flex: 1; min-width: 0; }
.at-chip.is-new { border-color: #c9a227; background: linear-gradient(90deg, #fdf6dc, #fff 70%); }
.at-chip em { margin-left: auto; font: 700 8.5px/1 Inter, sans-serif; letter-spacing: .14em; text-transform: uppercase; color: #8a6a00; font-style: normal; white-space: nowrap; }
.at-respond { display: flex; align-items: center; gap: 10px; width: 100%; border: 0; border-radius: 0; cursor: pointer; padding: 10px 12px; margin-top: 12px;
  background: linear-gradient(180deg, #1d3a69, #0d1d3a); color: #fff; box-shadow: inset 0 0 0 1px #c9a227; }
.at-rk { font: 800 9.5px/1 Inter, sans-serif; letter-spacing: .16em; color: #e5cc80; padding-right: 10px; border-right: 1px solid rgba(229, 204, 128, .5); }
.at-rt { flex: 1; text-align: left; font: italic 400 13px/1.2 Georgia, serif; color: #fff; }
.at-ra { font: 400 20px/1 Georgia, serif; color: #e5cc80; }

/* ─── The EI templates picker (dialog body) ──────────────────────── */
.at-pick { text-align: left; font: 400 12.5px/1.4 Inter, 'Segoe UI', sans-serif; color: #0f1f3d; }
.at-pick-p { margin: 0 0 10px; color: #475569; }
.at-pick-all { display: flex; align-items: center; gap: 8px; padding: 7px 2px; border-bottom: 1px solid #e2e8f0; font-weight: 600; cursor: pointer; }
.at-pick-list { max-height: 300px; overflow-y: auto; }
.at-pick-row { display: flex; align-items: center; gap: 8px; padding: 6px 2px; border-bottom: 1px solid #f1f5f9; cursor: pointer; }
.at-pick-row b { font: 400 13px/1.25 Georgia, serif; color: #13294b; }
.at-pick-row em { margin-left: 8px; font: 700 8.5px/1 Inter, sans-serif; letter-spacing: .12em; text-transform: uppercase; color: #8a6a00; font-style: normal; }

/* ─── Forge in the chat ──────────────────────────────────────────── */
.at-forge, .at-forge * { box-sizing: border-box; }
._eli3_chat_bubble.at-forge { align-self: stretch; max-width: none; background: transparent; border: 0; padding: 0; box-shadow: none; display: flex; flex-direction: column; gap: 10px;
  font: 400 12.5px/1.45 Inter, 'Segoe UI', sans-serif; color: #0f1f3d; }
.at-eli { background: #fff; border: 1px solid #d6dee9; border-left: 3px solid #13294b; padding: 9px 12px; font: 400 13px/1.45 Inter, sans-serif; }
.at-from { display: block; font: 700 9px/1 Inter, sans-serif; letter-spacing: .16em; color: #64748b; margin-bottom: 5px; }
.at-route { background: #fff; border: 1px solid #c9a227; padding: 4px; }
.at-route-in { border: 1px solid #e3e8ef; padding: 12px 12px 10px; background: linear-gradient(180deg, #fff, #fdf9ec); }
.at-path { display: flex; align-items: center; margin: 10px 0 8px; }
.at-ln { flex: 1; height: 0; border-top: 2px dotted #c9a227; margin: 0 4px; position: relative; transform-origin: left center; animation: at-draw .6s ease-out both; }
.at-ln::after { content: ""; position: absolute; right: -1px; top: -5px; width: 8px; height: 8px; border: solid #c9a227; border-width: 2px 2px 0 0; transform: rotate(45deg); }
.at-pnode { display: flex; flex-direction: column; align-items: center; text-align: center; width: 96px; }
.at-pnode b { font: 400 14px/1.15 Georgia, serif; color: #13294b; margin-top: 3px; }
.at-pnode span { font: italic 11px/1.2 Georgia, serif; color: #64748b; }
.at-dim .at-sl { opacity: .45; animation: at-light .4s ease-out .6s both; }
.at-route.is-gone { overflow: hidden; transition: max-height .35s ease-in, opacity .35s ease-in; max-height: 0 !important; opacity: 0; }
.at-route p { margin: 0; font: italic 13px/1.4 Georgia, serif; color: #334155; text-align: center; }
.at-div { display: flex; align-items: center; gap: 8px; font: 700 9px/1 Inter, sans-serif; letter-spacing: .16em; color: #8a6a00; text-transform: uppercase; }
.at-div::before, .at-div::after { content: ""; flex: 1; height: 1px; background: linear-gradient(90deg, transparent, #c9a227); }
.at-div::after { background: linear-gradient(90deg, #c9a227, transparent); }
.at-div.is-navy { color: #13294b; }
.at-arrive { display: flex; flex-direction: column; align-items: center; padding: 6px 0 2px; overflow: hidden; }
.at-arrive h3 { margin: 6px 0 1px; font: 400 22px/1.15 Georgia, serif; color: #13294b; }
.at-fn { font: italic 12.5px/1.3 Georgia, serif; color: #64748b; text-align: center; }
.at-tag { display: inline-block; margin-top: 8px; font: 800 9px/1 Inter, sans-serif; letter-spacing: .18em; color: #13294b; background: linear-gradient(180deg, #f3de9a, #c9a227); padding: 5px 8px; }
.at-promise { margin-top: 10px; display: flex; flex-direction: column; gap: 3px; font: 400 11.5px/1.35 Inter, sans-serif; color: #475569; }
.at-promise div::before { content: ""; display: inline-block; width: 5px; height: 5px; background: #c9a227; transform: rotate(45deg); margin: 0 8px 1px 0; }
.at-spring { animation: at-spring .55s cubic-bezier(.3, 1.5, .5, 1) both; }
.at-ring { transform-origin: center; animation: at-pulse 1.4s ease-out both; }
.at-ring1 { animation-delay: .15s; } .at-ring2 { animation-delay: .3s; }
.at-arrive.is-leaving { animation: at-leave .4s ease-in forwards; }
/* the agent bar, between Ask ELI's top and the chat */
.at-agentbar { display: flex; align-items: center; gap: 10px; padding: 8px 52px 8px 10px; background: linear-gradient(180deg, #1d3a69, #0d1d3a); border-bottom: 2px solid #c9a227;
  color: #fff; flex: 0 0 auto; animation: at-drop .35s ease-out both; }
.at-ab-t { flex: 1; min-width: 0; }
.at-ab-t b { font: 400 16px/1.1 Georgia, serif; color: #fff; }
.at-ab-t .at-tag { margin: 0 0 0 6px; padding: 3px 6px; font-size: 8px; vertical-align: 2px; }
.at-ab-t small { display: block; font: italic 11px/1.25 Georgia, serif; color: #9aa9c2; margin-top: 2px; text-wrap: balance; }   /* (two even lines at the pane's width, never cut) */
.at-ab-back { font: 700 9px/1 Inter, sans-serif; letter-spacing: .12em; text-transform: uppercase; color: #e5cc80; background: transparent; border: 1px solid rgba(229, 204, 128, .6);
  border-radius: 0; padding: 6px 7px; white-space: nowrap; cursor: pointer; }
.at-ab-back:hover { background: rgba(229, 204, 128, .12); }
/* Forge's replies */
.at-msg { display: flex; gap: 8px; align-items: flex-start; }
.at-card { flex: 1; min-width: 0; background: #fff; border: 1px solid #e3d6a6; border-left: 3px solid #c9a227; padding: 10px 12px; box-shadow: 0 2px 8px rgba(201, 162, 39, .10); animation: at-in .3s ease-out both; }
.at-who { font: 700 9px/1 Inter, sans-serif; letter-spacing: .16em; text-transform: uppercase; color: #8a6a00; margin-bottom: 6px; }
.at-lead { margin: 0 0 8px; font: 400 13px/1.45 Inter, sans-serif; }
.at-card > :last-child { margin-bottom: 0; }
.at-list { margin: 0 0 8px; padding-left: 18px; font: 400 12.5px/1.45 Inter, sans-serif; color: #334155; }
.at-checks { border-top: 1px solid #f0e6c4; border-bottom: 1px solid #f0e6c4; padding: 6px 0; margin: 2px 0 9px; display: flex; flex-direction: column; gap: 4px; }
.at-ck { display: flex; gap: 8px; align-items: baseline; font: 400 12px/1.35 Inter, sans-serif; color: #334155; animation: at-in .25s ease-out both; }
.at-ck span { margin-left: auto; font: italic 11.5px/1.2 Georgia, serif; color: #64748b; text-align: right; }
.at-ck i { font-style: normal; width: 14px; flex: 0 0 14px; font-weight: 700; }
.at-ck.is-ok i { color: #15803d; } .at-ck.is-warn i { color: #b45309; } .at-ck.is-info i { color: #94a3b8; }
.at-ck.is-warn { color: #0f1f3d; font-weight: 600; } .at-ck.is-warn span { color: #b45309; }
.at-acts { display: flex; flex-direction: column; gap: 6px; }
.at-go { display: flex; align-items: center; gap: 10px; width: 100%; border: 0; border-radius: 0; padding: 9px 11px; background: linear-gradient(180deg, #1d3a69, #0d1d3a);
  box-shadow: inset 0 0 0 1px #c9a227; cursor: pointer; text-align: left; }
.at-go .at-sl { margin: -2px 0; }
.at-go b { display: block; font: 400 14px/1.15 Georgia, serif; color: #fff; }
.at-go small { display: block; font: 400 10.5px/1.3 Inter, sans-serif; color: #9aa9c2; }
.at-go em { margin-left: auto; font: 400 20px/1 Georgia, serif; color: #e5cc80; font-style: normal; }
.at-go:disabled, .at-link:disabled { opacity: .55; cursor: default; }
.at-links { display: flex; gap: 14px; margin-top: 9px; }
.at-link { font: 400 12.5px/1 Georgia, serif; color: #13294b; background: none; border: 0; border-bottom: 1px solid #c9a227; border-radius: 0; padding: 0 0 2px; cursor: pointer; }
.at-dots { display: inline-flex; gap: 4px; margin-left: 6px; vertical-align: middle; }
.at-dots i { width: 5px; height: 5px; background: #c9a227; opacity: .3; animation: at-sq 1.2s infinite; }
.at-dots i:nth-child(2) { animation-delay: .2s; } .at-dots i:nth-child(3) { animation-delay: .4s; }
.at-card.is-working .at-lead { color: #64748b; font-style: italic; font-family: Georgia, serif; }
/* an agent run in the chat (Revise, Respond) takes the top: Forge's bar and label step aside */
._eli3_chat_root._eli3_ae_agent .at-agentbar, ._eli3_chat_root._eli3_ae_agent .at-reply { display: none; }
/* the input box while Forge is in */
._eli3_chat_root.at-forge-on ._eli3_chat_input { box-shadow: inset 0 0 0 1px #c9a227; border-color: #c9a227; }
.at-reply { display: flex; justify-content: space-between; gap: 10px; padding: 6px 2px 4px; font: 700 9px/1 Inter, sans-serif; letter-spacing: .12em; color: #8a6a00; text-transform: uppercase; }
.at-reply span { font: italic 400 11px/1 Georgia, serif; letter-spacing: 0; text-transform: none; color: #64748b; text-align: right; }

@keyframes at-draw { from { transform: scaleX(0); } to { transform: scaleX(1); } }
@keyframes at-light { to { opacity: 1; } }
@keyframes at-spring { 0% { transform: scale(.4); opacity: .3; } 100% { transform: scale(1); opacity: 1; } }
@keyframes at-pulse { 0% { transform: scale(.7); opacity: 0; } 40% { opacity: .9; } 100% { transform: scale(1.12); opacity: 0; } }
@keyframes at-drop { from { transform: translateY(-100%); opacity: 0; } to { transform: none; opacity: 1; } }
@keyframes at-in { from { transform: translateY(4px); opacity: 0; } to { transform: none; opacity: 1; } }
@keyframes at-leave { to { opacity: 0; transform: scale(.6); max-height: 0; margin: 0; padding: 0; } }
@keyframes at-sq { 0%, 100% { opacity: .3; } 50% { opacity: 1; } }
@media (prefers-reduced-motion: reduce) {
  .at-ln, .at-dim .at-sl, .at-spring, .at-ring, .at-agentbar, .at-card, .at-ck, .at-dots i, .at-arrive.is-leaving { animation: none !important; }
  .at-dim .at-sl { opacity: 1; }
  .at-ring { opacity: 0; }
}
